#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/drivers/retained_mem.h>
#include <zephyr/device.h>
#include <string.h>

#define TEST_BUFFER_SIZE 16

static void retained_mem_api_test_size(const struct device *dev)
{
	ssize_t size = retained_mem_size(dev);

	zassert_true(size >= 0, "retained_mem_size failed");
}

static void retained_mem_api_test_write_read(const struct device *dev)
{
	uint8_t buffer[TEST_BUFFER_SIZE];
	uint8_t data[TEST_BUFFER_SIZE];
	int ret;
	size_t size;

	size = retained_mem_size(dev);
	zassert_true(size >= TEST_BUFFER_SIZE, "Retained memory size is too small");

	/* Fill with some data */
	for (int i = 0; i < TEST_BUFFER_SIZE; i++) {
		buffer[i] = i;
	}

	ret = retained_mem_write(dev, 0, buffer, sizeof(buffer));
	zassert_equal(ret, 0, "retained_mem_write failed");

	ret = retained_mem_read(dev, 0, data, sizeof(data));
	zassert_equal(ret, 0, "retained_mem_read failed");

	zassert_mem_equal(data, buffer, sizeof(data), "data not equal to buffer");
}

static void retained_mem_api_test_clear(const struct device *dev)
{
	uint8_t buffer[TEST_BUFFER_SIZE];
	uint8_t data[TEST_BUFFER_SIZE];
	int ret;
	size_t size;

	size = retained_mem_size(dev);
	zassert_true(size >= TEST_BUFFER_SIZE, "Retained memory size is too small");

	/* Fill with some data */
	memset(buffer, 0xAA, sizeof(buffer));
	ret = retained_mem_write(dev, 0, buffer, sizeof(buffer));
	zassert_equal(ret, 0, "retained_mem_write failed");

	/* Clear memory */
	ret = retained_mem_clear(dev);
	zassert_equal(ret, 0, "retained_mem_clear failed");

	/* Read cleared memory */
	ret = retained_mem_read(dev, 0, data, sizeof(data));
	zassert_equal(ret, 0, "retained_mem_read failed");

	/* Check if memory is cleared */
	memset(buffer, 0, sizeof(buffer));
	zassert_mem_equal(data, buffer, sizeof(data), "data not equal to buffer");
}

ZTEST(retained_mem_api, test_size)
{
	const struct device *const dev = DEVICE_DT_GET(DT_NODELABEL(retained_ram0));

	zassert_true(device_is_ready(dev), "Retained memory device is not ready");

	retained_mem_api_test_size(dev);
}

ZTEST(retained_mem_api, test_write_read)
{
	const struct device *const dev = DEVICE_DT_GET(DT_NODELABEL(retained_ram0));

	zassert_true(device_is_ready(dev), "Retained memory device is not ready");

	retained_mem_api_test_write_read(dev);
}

ZTEST(retained_mem_api, test_clear)
{
	const struct device *const dev = DEVICE_DT_GET(DT_NODELABEL(retained_ram0));

	zassert_true(device_is_ready(dev), "Retained memory device is not ready");

	retained_mem_api_test_clear(dev);
}

ZTEST_SUITE(retained_mem_api, NULL, NULL, NULL, NULL, NULL);
